import { DataTypes } from 'sequelize';
import sequelize from '../config/database.js';
import { logInfo, logError, logSecurity } from '../utils/logger.js';

const AccountBalance = sequelize.define('AccountBalance', {
    id: {
        type: DataTypes.INTEGER,
        primaryKey: true,
        autoIncrement: true
    },
    accountId: {
        type: DataTypes.INTEGER,
        allowNull: false,
        references: {
            model: 'chartsOfAccounts',
            key: 'id'
        }
    },
    company_id: {
        type: DataTypes.INTEGER,
        allowNull: false,
        references: {
            model: 'companies',
            key: 'id'
        }
    },
    periodMonth: {
        type: DataTypes.INTEGER,
        allowNull: false,
        comment: 'Month (1-12)'
    },
    periodYear: {
        type: DataTypes.INTEGER,
        allowNull: false,
        comment: 'Fiscal year'
    },
    openingBalance: {
        type: DataTypes.DECIMAL(15, 2),
        defaultValue: 0
    },
    debitMovement: {
        type: DataTypes.DECIMAL(15, 2),
        defaultValue: 0
    },
    creditMovement: {
        type: DataTypes.DECIMAL(15, 2),
        defaultValue: 0
    },
    closingBalance: {
        type: DataTypes.DECIMAL(15, 2),
        defaultValue: 0
    },
    isLocked: {
        type: DataTypes.BOOLEAN,
        defaultValue: false,
        comment: 'Period is locked for further entries'
    },
    lockedDate: {
        type: DataTypes.DATE,
        allowNull: true
    }
}, {
    tableName: 'accountBalances',
    timestamps: true,
    underscored: true,
    created_at: 'created_at',
    updated_at: 'updated_at',
    paranoid: true,
    deletedAt: 'deleted_at',
    indexes: [
        { fields: ['account_id'] },
        { fields: ['company_id'] },
        { fields: ['period_year', 'period_month'] },
        { fields: ['account_id', 'company_id', 'period_year', 'period_month'], unique: true }
    ],
    hooks: {
        beforeCreate: async (balance, options) => {
            try {
                // 1️⃣ PERIOD VALIDATION
                if (!balance.periodMonth || balance.periodMonth < 1 || balance.periodMonth > 12) {
                    throw new Error(`Invalid month: ${balance.periodMonth}. Must be 1-12`);
                }
                if (!balance.periodYear || balance.periodYear < 2000 || balance.periodYear > 2100) {
                    throw new Error(`Invalid year: ${balance.periodYear}`);
                }

                // 2️⃣ BALANCE CALCULATION
                const openingBalance = parseFloat(balance.openingBalance || 0);
                const debitMov = parseFloat(balance.debitMovement || 0);
                const creditMov = parseFloat(balance.creditMovement || 0);
                balance.closingBalance = parseFloat((openingBalance + debitMov - creditMov).toFixed(2));

                // 3️⃣ DEFAULTS
                balance.isLocked = false;
                balance.lockedDate = null;

                // 4️⃣ PRECISION
                balance.openingBalance = parseFloat((openingBalance).toFixed(2));
                balance.debitMovement = parseFloat((debitMov).toFixed(2));
                balance.creditMovement = parseFloat((creditMov).toFixed(2));

                logInfo(`AccountBalance.beforeCreate: Balance calculated for period ${balance.periodYear}-${balance.periodMonth}`);
            } catch (error) {
                logError(`AccountBalance.beforeCreate error: ${error.message}`);
                throw error;
            }
        },

        beforeUpdate: async (balance, options) => {
            try {
                // 1️⃣ PREVENT UPDATES IF LOCKED
                if (balance._previousDataValues.isLocked === true) {
                    throw new Error('Cannot update locked period balances. Unlock period first.');
                }

                // 2️⃣ RECALCULATE CLOSING BALANCE (if movements changed)
                if (balance.changed('openingBalance') || balance.changed('debitMovement') || balance.changed('creditMovement')) {
                    const openingBalance = parseFloat(balance.openingBalance || 0);
                    const debitMov = parseFloat(balance.debitMovement || 0);
                    const creditMov = parseFloat(balance.creditMovement || 0);
                    balance.closingBalance = parseFloat((openingBalance + debitMov - creditMov).toFixed(2));

                    // Precision
                    balance.openingBalance = parseFloat((openingBalance).toFixed(2));
                    balance.debitMovement = parseFloat((debitMov).toFixed(2));
                    balance.creditMovement = parseFloat((creditMov).toFixed(2));
                }

                // 3️⃣ LOCK DATE MANAGEMENT
                if (balance.changed('isLocked')) {
                    if (balance.isLocked === true) {
                        balance.lockedDate = new Date();
                        logSecurity(`AccountBalance locked: ${balance.periodYear}-${balance.periodMonth}`);
                    } else {
                        balance.lockedDate = null;
                        logSecurity(`AccountBalance unlocked: ${balance.periodYear}-${balance.periodMonth}`);
                    }
                }

                logInfo(`AccountBalance.beforeUpdate: Balance prepared for update`);
            } catch (error) {
                logError(`AccountBalance.beforeUpdate error: ${error.message}`);
                throw error;
            }
        }
    }
});

export default AccountBalance;

// src/models/appSetting.model.js
import { DataTypes } from 'sequelize';
import { logInfo, logError, logSecurity } from '../utils/logger.js';

export default (sequelize) => {
  const AppSetting = sequelize.define(
    'AppSetting',
    {
      id: {
        type: DataTypes.INTEGER,
        primaryKey: true,
        autoIncrement: true
      },
      cle: {
        type: DataTypes.STRING(255),
        allowNull: false,
        unique: true,
        validate: {
          notEmpty: true
        }
      },
      valeur: {
        type: DataTypes.TEXT,
        allowNull: true
      },
      scope: {
        type: DataTypes.ENUM('GLOBAL', 'ENTREPRISE'),
        allowNull: false,
        defaultValue: 'GLOBAL',
        validate: {
          isIn: [['GLOBAL', 'ENTREPRISE']]
        }
      },
      groupe_id: {
        type: DataTypes.INTEGER,
        allowNull: true,
        references: {
          model: 'groupes_entreprises',
          key: 'id'
        }
      },
      description: {
        type: DataTypes.TEXT,
        allowNull: true
      },
      type_valeur: {
        type: DataTypes.ENUM('STRING', 'INTEGER', 'BOOLEAN', 'JSON'),
        defaultValue: 'STRING'
      },
      is_sensitive: {
        type: DataTypes.BOOLEAN,
        defaultValue: false
      },
      created_at: {
        type: DataTypes.DATE,
        allowNull: false,
        defaultValue: DataTypes.NOW
      },
      updated_at: {
        type: DataTypes.DATE,
        allowNull: false,
        defaultValue: DataTypes.NOW
      }
    },
    {
      tableName: 'app_settings',
      timestamps: true,
      freezeTableName: true,
      underscored: true,
      created_at: 'created_at',
      updated_at: 'updated_at',
      paranoid: true,
      deletedAt: 'deleted_at',
      hooks: {
        beforeCreate: async (setting, options) => {
          try {
            // 1️⃣ KEY NORMALIZATION
            setting.cle = setting.cle.trim().toUpperCase();
            if (setting.description) setting.description = setting.description.trim();

            // 2️⃣ VALUE TYPE VALIDATION & CONVERSION
            if (setting.valeur && setting.type_valeur) {
              try {
                if (setting.type_valeur === 'BOOLEAN') {
                  setting.valeur = String(setting.valeur).toLowerCase() === 'true' ? 'true' : 'false';
                } else if (setting.type_valeur === 'INTEGER') {
                  const intVal = parseInt(setting.valeur, 10);
                  if (isNaN(intVal)) throw new Error('Invalid integer value');
                  setting.valeur = String(intVal);
                } else if (setting.type_valeur === 'JSON') {
                  JSON.parse(setting.valeur); // Validate JSON
                }
                // STRING: no conversion needed
              } catch (error) {
                throw new Error(`Invalid value for type ${setting.type_valeur}: ${error.message}`);
              }
            }

            // 3️⃣ SCOPE VALIDATION
            if (setting.scope === 'ENTREPRISE' && !setting.groupe_id) {
              throw new Error('groupe_id required for ENTREPRISE scope');
            }

            logInfo(`AppSetting.beforeCreate: Setting ${setting.cle} prepared`);
            if (setting.is_sensitive) {
              logSecurity(`Sensitive setting modified: ${setting.cle}`);
            }
          } catch (error) {
            logError(`AppSetting.beforeCreate error: ${error.message}`);
            throw error;
          }
        },

        beforeUpdate: async (setting, options) => {
          try {
            // 1️⃣ KEY IMMUTABILITY
            if (setting.changed('cle')) {
              throw new Error('Cannot change setting key');
            }

            // 2️⃣ VALUE TYPE VALIDATION (if changed)
            if (setting.changed('valeur') && setting.valeur && setting.type_valeur) {
              try {
                if (setting.type_valeur === 'BOOLEAN') {
                  setting.valeur = String(setting.valeur).toLowerCase() === 'true' ? 'true' : 'false';
                } else if (setting.type_valeur === 'INTEGER') {
                  const intVal = parseInt(setting.valeur, 10);
                  if (isNaN(intVal)) throw new Error('Invalid integer value');
                  setting.valeur = String(intVal);
                } else if (setting.type_valeur === 'JSON') {
                  JSON.parse(setting.valeur);
                }
              } catch (error) {
                throw new Error(`Invalid value for type ${setting.type_valeur}`);
              }
            }

            // 3️⃣ SENSITIVE SETTING LOGGING
            if (setting.changed('valeur') && setting.is_sensitive) {
              logSecurity(`Sensitive setting updated: ${setting.cle}`);
            }

            logInfo(`AppSetting.beforeUpdate: Setting ${setting.cle} prepared for update`);
          } catch (error) {
            logError(`AppSetting.beforeUpdate error: ${error.message}`);
            throw error;
          }
        }
      }
    }
  );

  return AppSetting;
};

// src/models/associations.js - Associations Sequelize pour SPOFE v2.1
export const defineAssociations = (models) => {
  const {
    User,
    Role,
    GroupeEntreprise,
    Compagnie,
    AppSetting,
    AuditTrail,
    Compagnie,
    JournalEntry,
    ChartOfAccount,
    JournalEntryLine
  } = models;

  // ===== ROLE Associations =====
  Role.hasMany(User, {
    foreignKey: 'role_id',
    as: 'users',
    onDelete: 'RESTRICT',
    onUpdate: 'CASCADE'
  });

  // ===== GROUPE_ENTREPRISE Associations =====
  GroupeEntreprise.hasMany(User, {
    foreignKey: 'groupe_id',
    as: 'utilisateurs',
    onDelete: 'CASCADE',
    onUpdate: 'CASCADE'
  });

  GroupeEntreprise.hasMany(Compagnie, {
    foreignKey: 'groupe_id',
    as: 'compagnies',
    onDelete: 'CASCADE',
    onUpdate: 'CASCADE'
  });

  GroupeEntreprise.hasMany(AppSetting, {
    foreignKey: 'groupe_id',
    as: 'settings',
    onDelete: 'CASCADE',
    onUpdate: 'CASCADE'
  });

  // ===== USER Associations =====
  User.belongsTo(Role, {
    foreignKey: 'role_id',
    as: 'role',
    onDelete: 'RESTRICT',
    onUpdate: 'CASCADE'
  });

  User.belongsTo(GroupeEntreprise, {
    foreignKey: 'groupe_id',
    as: 'groupe',
    onDelete: 'CASCADE',
    onUpdate: 'CASCADE'
  });

  User.hasMany(AuditTrail, {
    foreignKey: 'utilisateur_id',
    as: 'audits',
    onDelete: 'SET NULL',
    onUpdate: 'CASCADE'
  });

  // ===== COMPAGNIE Associations =====
  Compagnie.belongsTo(GroupeEntreprise, {
    foreignKey: 'groupe_id',
    as: 'groupe',
    onDelete: 'CASCADE',
    onUpdate: 'CASCADE'
  });

  // ===== APP_SETTING Associations =====
  AppSetting.belongsTo(GroupeEntreprise, {
    foreignKey: 'groupe_id',
    as: 'groupe',
    onDelete: 'CASCADE',
    onUpdate: 'CASCADE'
  });

  // ===== AUDIT_TRAIL Associations =====
  AuditTrail.belongsTo(User, {
    foreignKey: 'utilisateur_id',
    as: 'utilisateur',
    onDelete: 'SET NULL',
    onUpdate: 'CASCADE'
  });

  // ===== COMPANY Associations =====
  if (Compagnie && JournalEntry) {
    Compagnie.hasMany(JournalEntry, {
      foreignKey: 'company_id',
      as: 'journalEntries',
      onDelete: 'CASCADE',
      onUpdate: 'CASCADE'
    });

    JournalEntry.belongsTo(Compagnie, {
      foreignKey: 'company_id',
      as: 'company',
      onDelete: 'CASCADE',
      onUpdate: 'CASCADE'
    });
  }

  if (Compagnie && ChartOfAccount) {
    Compagnie.hasMany(ChartOfAccount, {
      foreignKey: 'company_id',
      as: 'chartsOfAccounts',
      onDelete: 'CASCADE',
      onUpdate: 'CASCADE'
    });

    ChartOfAccount.belongsTo(Compagnie, {
      foreignKey: 'company_id',
      as: 'company',
      onDelete: 'CASCADE',
      onUpdate: 'CASCADE'
    });
  }

  // ===== USER Associations =====
  if (User && JournalEntry) {
    User.hasMany(JournalEntry, {
      foreignKey: 'user_id',
      as: 'journalEntries',
      onDelete: 'SET NULL',
      onUpdate: 'CASCADE'
    });

    JournalEntry.belongsTo(User, {
      foreignKey: 'user_id',
      as: 'createdBy',
      onDelete: 'SET NULL',
      onUpdate: 'CASCADE'
    });
  }

  // ===== JOURNAL_ENTRY Associations =====
  if (JournalEntry && JournalEntryLine) {
    JournalEntry.hasMany(JournalEntryLine, {
      foreignKey: 'entry_id',
      as: 'lines',
      onDelete: 'CASCADE',
      onUpdate: 'CASCADE'
    });

    JournalEntryLine.belongsTo(JournalEntry, {
      foreignKey: 'entry_id',
      as: 'entry',
      onDelete: 'CASCADE',
      onUpdate: 'CASCADE'
    });
  }
};

// src/models/auditTrail.model.js
import { DataTypes } from 'sequelize';

export default (sequelize) => {
  const AuditTrail = sequelize.define(
    'AuditTrail',
    {
      id: {
        type: DataTypes.INTEGER,
        primaryKey: true,
        autoIncrement: true
      },
      table_name: {
        type: DataTypes.STRING(100),
        allowNull: false,
        index: true,
        validate: {
          notEmpty: true
        }
      },
      record_id: {
        type: DataTypes.INTEGER,
        allowNull: false,
        index: true
      },
      operation: {
        type: DataTypes.ENUM('CREATE', 'UPDATE', 'DELETE'),
        allowNull: false,
        validate: {
          isIn: [['CREATE', 'UPDATE', 'DELETE']]
        }
      },
      old_values: {
        type: DataTypes.JSON,
        allowNull: true
      },
      new_values: {
        type: DataTypes.JSON,
        allowNull: true
      },
      utilisateur_id: {
        type: DataTypes.INTEGER,
        allowNull: true,
        references: {
          model: 'users',
          key: 'id'
        }
      },
      ip_address: {
        type: DataTypes.STRING(45),
        allowNull: true,
        validate: {
          isIP: true
        }
      },
      user_agent: {
        type: DataTypes.TEXT,
        allowNull: true
      },
      created_at: {
        type: DataTypes.DATE,
        allowNull: false,
        defaultValue: DataTypes.NOW,
        index: true
      }
    },
    {
      tableName: 'audit_trail',
      timestamps: false,
      freezeTableName: true,
      underscored: true
    }
  );

  return AuditTrail;
};

/**
 * Modèle: BusinessOperation
 * 
 * Représente une opération métier pré-comptable
 * 
 * Workflow:
 * 1. USER crée (DRAFT)
 * 2. USER soumet (PENDING_VALIDATION)
 * 3. ADMIN valide/rejette (VALIDATED/REJECTED)
 * 4. Si validé → création écriture comptable
 * 
 * Règles métier critiques:
 * - Modification interdite après soumission (sauf par ADMIN)
 * - Validation = création écriture comptable atomique
 * - Traçabilité complète via audits
 */

import { DataTypes } from 'sequelize';
import sequelize from '../config/database.js';

const BusinessOperation = sequelize.define('BusinessOperation', {
  id: {
    type: DataTypes.BIGINT.UNSIGNED,
    primaryKey: true,
    autoIncrement: true
  },

  operationType: {
    type: DataTypes.ENUM('CAISSE', 'BANQUE', 'IMMO', 'STOCK', 'CREANCE', 'DETTE'),
    allowNull: false,
    field: 'operation_type',
    validate: {
      isIn: {
        args: [['CAISSE', 'BANQUE', 'IMMO', 'STOCK', 'CREANCE', 'DETTE']],
        msg: 'Type d\'opération invalide'
      }
    }
  },

  label: {
    type: DataTypes.STRING(150),
    allowNull: false,
    validate: {
      notEmpty: {
        msg: 'Le libellé est obligatoire'
      },
      len: {
        args: [3, 150],
        msg: 'Le libellé doit contenir entre 3 et 150 caractères'
      }
    }
  },

  description: {
    type: DataTypes.TEXT,
    allowNull: true
  },

  amount: {
    type: DataTypes.DECIMAL(15, 2),
    allowNull: false,
    validate: {
      min: {
        args: [0.01],
        msg: 'Le montant doit être supérieur à 0'
      }
    }
  },

  currencyCode: {
    type: DataTypes.CHAR(3),
    allowNull: false,
    defaultValue: 'XOF',
    field: 'currency_code',
    validate: {
      len: {
        args: [3, 3],
        msg: 'Le code devise doit contenir 3 caractères'
      }
    }
  },

  exchangeRate: {
    type: DataTypes.DECIMAL(10, 6),
    allowNull: false,
    defaultValue: 1.000000,
    field: 'exchange_rate',
    validate: {
      min: {
        args: [0.000001],
        msg: 'Le taux de change doit être positif'
      }
    }
  },

  operationDate: {
    type: DataTypes.DATE,
    allowNull: false,
    field: 'operation_date',
    validate: {
      isDate: {
        msg: 'Date d\'opération invalide'
      }
    }
  },

  fiscalYearId: {
    type: DataTypes.INTEGER,
    allowNull: false,
    field: 'fiscal_year_id',
    references: {
      model: 'fiscal_years',
      key: 'id'
    }
  },

  thirdPartyId: {
    type: DataTypes.BIGINT.UNSIGNED,
    allowNull: true,
    field: 'third_party_id',
    references: {
      model: 'third_parties',
      key: 'id'
    }
  },

  attachmentUrl: {
    type: DataTypes.STRING(255),
    allowNull: true,
    field: 'attachment_url',
    validate: {
      isUrl: {
        msg: 'URL de pièce jointe invalide'
      }
    }
  },

  status: {
    type: DataTypes.ENUM('DRAFT', 'PENDING_VALIDATION', 'VALIDATED', 'REJECTED'),
    allowNull: false,
    defaultValue: 'DRAFT',
    validate: {
      isIn: {
        args: [['DRAFT', 'PENDING_VALIDATION', 'VALIDATED', 'REJECTED']],
        msg: 'Statut invalide'
      }
    }
  },

  createdBy: {
    type: DataTypes.INTEGER,
    allowNull: false,
    field: 'created_by',
    references: {
      model: 'users',
      key: 'id'
    }
  },

  validatedBy: {
    type: DataTypes.INTEGER,
    allowNull: true,
    field: 'validated_by',
    references: {
      model: 'users',
      key: 'id'
    }
  },

  validatedAt: {
    type: DataTypes.DATE,
    allowNull: true,
    field: 'validated_at'
  },

  rejectionReason: {
    type: DataTypes.TEXT,
    allowNull: true,
    field: 'rejection_reason'
  },

  proposedJournalEntryId: {
    type: DataTypes.INTEGER,
    allowNull: true,
    field: 'proposed_journal_entry_id',
    references: {
      model: 'journal_entries',
      key: 'id'
    }
  },

  deletedAt: {
    type: DataTypes.DATE,
    allowNull: true,
    field: 'deleted_at'
  }
}, {
  tableName: 'business_operations',
  timestamps: true,
  underscored: true,
  paranoid: true, // Active le soft delete
  created_at: 'created_at',
  updated_at: 'updated_at',
  deletedAt: 'deleted_at',

  hooks: {
    /**
     * Avant validation: vérifications métier
     */
    beforeValidate: (operation) => {
      // Normaliser le libellé
      if (operation.label) {
        operation.label = operation.label.trim();
      }

      // Validation de la date dans l'exercice
      // TODO: Implémenter la vérification que operation_date est dans fiscal_year
    },

    /**
     * Avant mise à jour: protections OHADA
     */
    beforeUpdate: (operation) => {
      // RÈGLE CRITIQUE: Interdiction de modifier une opération validée
      if (operation.changed('status') && 
          operation._previousDataValues.status === 'VALIDATED') {
        throw new Error(
          'Impossible de modifier une opération validée. ' +
          'Toute correction doit passer par une contre-passation.'
        );
      }

      // Validation du workflow
      if (operation.changed('status')) {
        const oldStatus = operation._previousDataValues.status;
        const newStatus = operation.status;

        // Transitions valides
        const validTransitions = {
          'DRAFT': ['PENDING_VALIDATION'],
          'PENDING_VALIDATION': ['VALIDATED', 'REJECTED', 'DRAFT'],
          'REJECTED': ['DRAFT'],
          'VALIDATED': [] // Aucune transition possible
        };

        if (!validTransitions[oldStatus].includes(newStatus)) {
          throw new Error(
            `Transition invalide: ${oldStatus} → ${newStatus}`
          );
        }
      }

      // Validation obligatoire: validated_by pour VALIDATED
      if (operation.status === 'VALIDATED' && !operation.validatedBy) {
        throw new Error('Le champ validated_by est obligatoire pour valider une opération');
      }

      // Rejet obligatoire: rejection_reason pour REJECTED
      if (operation.status === 'REJECTED' && !operation.rejectionReason) {
        throw new Error('Le motif de rejet est obligatoire');
      }

      // Horodatage automatique de la validation
      if (operation.changed('status') && operation.status === 'VALIDATED') {
        operation.validatedAt = new Date();
      }
    },

    /**
     * Avant suppression: log d'audit
     */
    beforeDestroy: async (operation) => {
      // Interdire la suppression physique des opérations validées
      if (operation.status === 'VALIDATED') {
        throw new Error(
          'Suppression interdite pour les opérations validées. ' +
          'Utilisez une contre-passation.'
        );
      }
    }
  }
});

/**
 * Méthodes d'instance
 */
BusinessOperation.prototype.canBeEditedBy = function(user) {
  // ADMIN peut tout modifier (sauf VALIDATED)
  if (user.role === 'admin' && this.status !== 'VALIDATED') {
    return true;
  }

  // USER peut modifier ses propres DRAFT
  if (user.id === this.createdBy && this.status === 'DRAFT') {
    return true;
  }

  return false;
};

BusinessOperation.prototype.canBeValidatedBy = function(user) {
  return ['admin', 'accountant'].includes(user.role) && 
         this.status === 'PENDING_VALIDATION';
};

BusinessOperation.prototype.canBeRejectedBy = function(user) {
  return ['admin', 'accountant'].includes(user.role) && 
         this.status === 'PENDING_VALIDATION';
};

/**
 * Méthodes statiques
 */
BusinessOperation.findByStatus = function(status, options = {}) {
  return this.findAll({
    where: { status },
    order: [['operation_date', 'DESC']],
    ...options
  });
};

BusinessOperation.findPendingValidation = function(options = {}) {
  return this.findByStatus('PENDING_VALIDATION', options);
};

BusinessOperation.findByUser = function(user_id, options = {}) {
  return this.findAll({
    where: { createdBy: user_id },
    order: [['created_at', 'DESC']],
    ...options
  });
};

export default BusinessOperation;

/**
 * Modèle: BusinessOperationAudit
 * 
 * Traçabilité complète des actions sur les opérations métier
 * 
 * Conformité OHADA Article 18:
 * - Toute modification est tracée
 * - Aucune suppression d'historique
 * - Identification de l'auteur obligatoire
 */

import { DataTypes } from 'sequelize';
import sequelize from '../config/database.js';

const BusinessOperationAudit = sequelize.define('BusinessOperationAudit', {
  id: {
    type: DataTypes.BIGINT.UNSIGNED,
    primaryKey: true,
    autoIncrement: true
  },

  businessOperationId: {
    type: DataTypes.BIGINT.UNSIGNED,
    allowNull: false,
    field: 'business_operation_id',
    references: {
      model: 'business_operations',
      key: 'id'
    }
  },

  action: {
    type: DataTypes.ENUM('CREATE', 'UPDATE', 'SUBMIT', 'VALIDATE', 'REJECT', 'DELETE'),
    allowNull: false,
    validate: {
      isIn: {
        args: [['CREATE', 'UPDATE', 'SUBMIT', 'VALIDATE', 'REJECT', 'DELETE']],
        msg: 'Action invalide'
      }
    }
  },

  performedBy: {
    type: DataTypes.INTEGER,
    allowNull: false,
    field: 'performed_by',
    references: {
      model: 'users',
      key: 'id'
    }
  },

  comment: {
    type: DataTypes.TEXT,
    allowNull: true
  },

  oldValues: {
    type: DataTypes.JSON,
    allowNull: true,
    field: 'old_values'
  },

  newValues: {
    type: DataTypes.JSON,
    allowNull: true,
    field: 'new_values'
  },

  ipAddress: {
    type: DataTypes.STRING(45),
    allowNull: true,
    field: 'ip_address'
  },

  userAgent: {
    type: DataTypes.STRING(255),
    allowNull: true,
    field: 'user_agent'
  },

  performedAt: {
    type: DataTypes.DATE,
    allowNull: false,
    defaultValue: DataTypes.NOW,
    field: 'performed_at'
  }
}, {
  tableName: 'business_operation_audits',
  timestamps: false, // On utilise performedAt au lieu de timestamps classiques
  underscored: true
});

/**
 * Méthodes statiques
 */
BusinessOperationAudit.logAction = async function(businessOperationId, action, performedBy, options = {}) {
  const { comment, oldValues, newValues, ipAddress, userAgent } = options;

  return this.create({
    businessOperationId,
    action,
    performedBy,
    comment,
    oldValues,
    newValues,
    ipAddress,
    userAgent,
    performedAt: new Date()
  });
};

BusinessOperationAudit.getHistory = function(businessOperationId, options = {}) {
  return this.findAll({
    where: { businessOperationId },
    include: [{
      association: 'performer',
      attributes: ['id', 'username', 'email', 'role']
    }],
    order: [['performed_at', 'DESC']],
    ...options
  });
};

BusinessOperationAudit.getUserActions = function(user_id, options = {}) {
  return this.findAll({
    where: { performedBy: user_id },
    order: [['performed_at', 'DESC']],
    limit: 100,
    ...options
  });
};

BusinessOperationAudit.getRecentActions = function(limit = 50) {
  return this.findAll({
    include: [
      {
        association: 'performer',
        attributes: ['id', 'username', 'email', 'role']
      },
      {
        association: 'businessOperation',
        attributes: ['id', 'label', 'status', 'amount']
      }
    ],
    order: [['performed_at', 'DESC']],
    limit
  });
};

export default BusinessOperationAudit;

import { DataTypes } from 'sequelize';
import sequelize from '../config/database.js';
import { logInfo, logError, logSecurity } from '../utils/logger.js';

const ChartOfAccount = sequelize.define('ChartOfAccount', {
    id: {
        type: DataTypes.INTEGER,
        primaryKey: true,
        autoIncrement: true
    },
    company_id: {
        type: DataTypes.INTEGER,
        allowNull: false,
        references: {
            model: 'compagnies',
            key: 'id'
        }
    },
    accountNumber: {
        type: DataTypes.STRING(20),
        allowNull: false,
        comment: 'OHADA account number (e.g., 101, 201, 301)'
    },
    accountName: {
        type: DataTypes.STRING,
        allowNull: false
    },
    accountType: {
        type: DataTypes.ENUM('ASSETS', 'LIABILITIES', 'EQUITY', 'REVENUES', 'EXPENSES', 'OTHER'),
        allowNull: false
    },
    subAccountType: {
        type: DataTypes.STRING(100),
        allowNull: true,
        comment: 'Sub-classification (e.g., BANK, CASH, INVENTORY)'
    },
    description: {
        type: DataTypes.TEXT,
        allowNull: true
    },
    parentAccountId: {
        type: DataTypes.INTEGER,
        allowNull: true,
        references: {
            model: 'charts_of_accounts',
            key: 'id'
        },
        comment: 'For hierarchical accounts'
    },
    is_active: {
        type: DataTypes.BOOLEAN,
        defaultValue: true
    },
    isTaxable: {
        type: DataTypes.BOOLEAN,
        defaultValue: false
    },
    allowSubAccounts: {
        type: DataTypes.BOOLEAN,
        defaultValue: true
    },
    level: {
        type: DataTypes.INTEGER,
        defaultValue: 1,
        comment: 'Hierarchy level (1=main, 2=sub, etc.)'
    }
}, {
    tableName: 'charts_of_accounts',
    timestamps: true,
    underscored: true,
    created_at: 'created_at',
    updated_at: 'updated_at',
    paranoid: true,
    deletedAt: 'deleted_at',
    indexes: [
        { fields: ['company_id'] },
        { fields: ['account_number', 'company_id'], unique: true }
    ],
    hooks: {
        beforeCreate: async (account, options) => {
            try {
                // 1️⃣ OHADA VALIDATION - Format: XXX (3 digits)
                const ohadaPattern = /^\d{1,3}$/;
                if (!ohadaPattern.test(account.accountNumber)) {
                    throw new Error(`Invalid OHADA account number: ${account.accountNumber}. Expected format: 1-3 digits (e.g., 101, 201)`);
                }

                // 2️⃣ NORMALIZATION
                account.accountNumber = account.accountNumber.trim().padStart(3, '0');
                account.accountName = account.accountName.trim();
                account.accountType = account.accountType.toUpperCase();
                if (account.description) account.description = account.description.trim();
                if (account.subAccountType) account.subAccountType = account.subAccountType.toUpperCase().trim();

                // 3️⃣ HIERARCHY LEVEL CALCULATION
                if (!account.level) {
                    account.level = account.parentAccountId ? 2 : 1;
                }

                // 4️⃣ ACTIVE BY DEFAULT
                if (account.is_active === null || account.is_active === undefined) {
                    account.is_active = true;
                }

                logInfo(`ChartOfAccount.beforeCreate: Account ${account.accountNumber} (${account.accountName}) prepared`);
                logSecurity(`Chart of account created: ${account.accountNumber} - ${account.accountName}`);
            } catch (error) {
                logError(`ChartOfAccount.beforeCreate error: ${error.message}`);
                throw error;
            }
        },

        beforeUpdate: async (account, options) => {
            try {
                // 1️⃣ ACCOUNT NUMBER VALIDATION (if changed)
                if (account.changed('accountNumber')) {
                    const ohadaPattern = /^\d{1,3}$/;
                    if (!ohadaPattern.test(account.accountNumber)) {
                        throw new Error(`Invalid OHADA account number: ${account.accountNumber}`);
                    }
                    account.accountNumber = account.accountNumber.trim().padStart(3, '0');
                }

                // 2️⃣ PREVENT PARENT CHANGE FOR MAIN ACCOUNTS
                if (account.changed('parentAccountId') && account.level === 1 && account._previousDataValues.parentAccountId === null) {
                    throw new Error('Cannot change parent for main-level accounts');
                }

                // 3️⃣ NORMALIZATION (if changed)
                if (account.changed('accountName')) {
                    account.accountName = account.accountName.trim();
                }
                if (account.changed('description')) {
                    account.description = account.description ? account.description.trim() : null;
                }

                // 4️⃣ STATUS CHANGE LOGGING
                if (account.changed('is_active')) {
                    const status = account.is_active ? 'ACTIVATED' : 'DEACTIVATED';
                    logSecurity(`Chart account status: ${account.accountNumber} → ${status}`);
                }

                logInfo(`ChartOfAccount.beforeUpdate: Account ${account.accountNumber} prepared for update`);
            } catch (error) {
                logError(`ChartOfAccount.beforeUpdate error: ${error.message}`);
                throw error;
            }
        },

        afterCreate: async (account, options) => {
            try {
                // AUDIT TRAIL
                if (options.sequelize) {
                    const { AuditTrail } = options.sequelize.models;
                    if (AuditTrail) {
                        await AuditTrail.create({
                            entityType: 'ChartOfAccount',
                            entityId: account.id,
                            action: 'CREATE',
                            changes: {
                                accountNumber: account.accountNumber,
                                accountName: account.accountName,
                                accountType: account.accountType
                            },
                            user_id: options.user_id,
                            ipAddress: options.ipAddress
                        });
                        logInfo(`ChartOfAccount.afterCreate: Audit trail for ${account.accountNumber}`);
                    }
                }
            } catch (error) {
                logError(`ChartOfAccount.afterCreate error: ${error.message}`);
            }
        }
    }
});

export default ChartOfAccount;

